func (t Command) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Command) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "catalog.ingredient.create":
		return t.AsCmdCatalogIngredientCreate()
	case "catalog.location.create":
		return t.AsCmdCatalogLocationCreate()
	case "catalog.location.delete":
		return t.AsCmdCatalogLocationDelete()
	case "catalog.location.update":
		return t.AsCmdCatalogLocationUpdate()
	case "catalog.product.create":
		return t.AsCmdCatalogProductCreate()
	case "catalog.product.delete":
		return t.AsCmdCatalogProductDelete()
	case "catalog.product.set_ingredient":
		return t.AsCmdCatalogProductSetIngredient()
	case "catalog.product.update":
		return t.AsCmdCatalogProductUpdate()
	case "catalog.store.create":
		return t.AsCmdCatalogStoreCreate()
	case "catalog.store.delete":
		return t.AsCmdCatalogStoreDelete()
	case "catalog.store.update":
		return t.AsCmdCatalogStoreUpdate()
	case "inventory.stock.add":
		return t.AsCmdInventoryStockAdd()
	case "inventory.stock.adjust":
		return t.AsCmdInventoryStockAdjust()
	case "inventory.stock.consume":
		return t.AsCmdInventoryStockConsume()
	case "inventory.stock.discard":
		return t.AsCmdInventoryStockDiscard()
	case "inventory.stock.freeze":
		return t.AsCmdInventoryStockFreeze()
	case "inventory.stock.mark_low":
		return t.AsCmdInventoryStockMarkLow()
	case "inventory.stock.move":
		return t.AsCmdInventoryStockMove()
	case "inventory.stock.open":
		return t.AsCmdInventoryStockOpen()
	case "inventory.stock.restock":
		return t.AsCmdInventoryStockRestock()
	case "inventory.stock.set_level":
		return t.AsCmdInventoryStockSetLevel()
	case "inventory.stock.split":
		return t.AsCmdInventoryStockSplit()
	case "inventory.stock.thaw":
		return t.AsCmdInventoryStockThaw()
	case "inventory.stock.unmark_low":
		return t.AsCmdInventoryStockUnmarkLow()
	case "inventory.stock.update":
		return t.AsCmdInventoryStockUpdate()
	case "shopping.item.add":
		return t.AsCmdShoppingItemAdd()
	case "shopping.item.check":
		return t.AsCmdShoppingItemCheck()
	case "shopping.item.clear_checked":
		return t.AsCmdShoppingItemClearChecked()
	case "shopping.item.delete":
		return t.AsCmdShoppingItemDelete()
	case "shopping.item.reorder":
		return t.AsCmdShoppingItemReorder()
	case "shopping.item.uncheck":
		return t.AsCmdShoppingItemUncheck()
	case "shopping.item.update":
		return t.AsCmdShoppingItemUpdate()
	case "shopping.list.create":
		return t.AsCmdShoppingListCreate()
	case "shopping.list.delete":
		return t.AsCmdShoppingListDelete()
	case "shopping.list.rename":
		return t.AsCmdShoppingListRename()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

